BEGIN;
create temp table assertion_count(n int);insert into assertion_count values(0);
create function pg_temp.check_it(v boolean,label text)returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Assertion failed: %',label;end if;update assertion_count set n=n+1;end$$;
create function pg_temp.throws(statement text,label text)returns void language plpgsql as $$declare failed boolean:=false;begin begin execute statement;exception when others then failed:=true;end;perform pg_temp.check_it(failed,label);end$$;
create temp table st(k text primary key,v jsonb);
insert into public.organizations(id,name,settings)values('ee630000-0000-4000-8000-000000000001','Account settings SQL fixture','{"private":"PRIVATE-ORG-FIXTURE","notifications":{"daily_summary":true}}'),('ee630000-0000-4000-8000-000000000002','Other account settings SQL fixture','{}');
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at,raw_user_meta_data)select ('ee630000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','account-'||n||'@fixture.invalid',clock_timestamp(),clock_timestamp(),clock_timestamp(),'{"full_name":"Original metadata name","private":"PRIVATE-AUTH-FIXTURE"}'from generate_series(101,103)n;
insert into public.profiles(id,org_id,role,full_name,preferences)select ('ee630000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case when n=103 then'ee630000-0000-4000-8000-000000000002'::uuid else'ee630000-0000-4000-8000-000000000001'::uuid end,case when n=101 then'admin'else'viewer'end,'Original profile name','{"private":"PRIVATE-PREFERENCE-FIXTURE"}'from generate_series(101,103)n on conflict(id)do update set org_id=excluded.org_id,role=excluded.role,full_name=excluded.full_name,preferences=excluded.preferences;
create function pg_temp.read_account(b jsonb default'{}',a uuid default'ee630000-0000-4000-8000-000000000101')returns jsonb language sql as $$select public.read_account_settings(a,'ee630000-0000-4000-8000-000000000001',b)$$;
create function pg_temp.decide(i uuid,b jsonb,a uuid default'ee630000-0000-4000-8000-000000000101')returns jsonb language sql as $$select public.decide_account_settings(i,'ee630000-0000-4000-8000-000000000001',a,b)$$;
create function pg_temp.org_input(name text default'Reviewed organization name')returns jsonb language sql as $$select jsonb_build_object('operation','save_organization','section','organization','sourceHash',public.knowledge_hash(public.account_organization_source('ee630000-0000-4000-8000-000000000001')),'confirmed',true,'reason','Review exact organization settings','name',name,'timezone','America/Chicago')$$;
create function pg_temp.personal_input(a uuid default'ee630000-0000-4000-8000-000000000102',name text default'Reviewed display name')returns jsonb language sql as $$select jsonb_build_object('operation','save_profile','section','personal','sourceHash',public.knowledge_hash(public.account_personal_source(a)),'confirmed',true,'reason','Review my exact display name','fullName',name)$$;
create function pg_temp.appearance_input(a uuid default'ee630000-0000-4000-8000-000000000102')returns jsonb language sql as $$select jsonb_build_object('operation','save_preferences','section','personal','sourceHash',public.knowledge_hash(public.account_personal_source(a)),'confirmed',true,'reason','Review my console appearance','theme','dark','accentColor','emerald')$$;
select pg_temp.check_it(pg_temp.read_account()->>'state'='ready','current verified member can read settings');
select pg_temp.check_it(pg_temp.read_account()::text not like'%PRIVATE-%','settings projection excludes private organization preference and auth payloads');
select pg_temp.check_it(pg_temp.read_account()->'organization'->'timezone'='null','unsupplied timezone is not invented');
select pg_temp.check_it(pg_temp.read_account('{}','ee630000-0000-4000-8000-000000000103')->>'state'='forbidden','cross organization settings held');
select pg_temp.check_it(pg_temp.decide('ee630000-0000-4000-8000-000000000201',pg_temp.org_input(),'ee630000-0000-4000-8000-000000000102')->>'state'='forbidden','viewer cannot save organization settings');
insert into st values('orgInput',pg_temp.org_input());
select pg_temp.check_it(pg_temp.decide('ee630000-0000-4000-8000-000000000201',(select v from st where k='orgInput'))->>'state'='saved','organization settings and decision save');
select pg_temp.check_it(pg_temp.decide('ee630000-0000-4000-8000-000000000201',(select v from st where k='orgInput'))->>'state'='replayed','lost organization response replays exactly');
select pg_temp.check_it(pg_temp.decide('ee630000-0000-4000-8000-000000000202',(select v from st where k='orgInput'))->>'state'='settings_changed','stale organization review held');
select pg_temp.check_it(pg_temp.decide('ee630000-0000-4000-8000-000000000201',pg_temp.org_input('Changed request'))->>'state'='request_conflict','changed input cannot reuse successful request');
select pg_temp.check_it((select settings->>'private'='PRIVATE-ORG-FIXTURE'and settings->'notifications'->'daily_summary'='true'from public.organizations where id='ee630000-0000-4000-8000-000000000001'),'supported organization save preserves unrelated stored settings without enabling delivery');
select pg_temp.check_it(exists(select 1 from public.shared_action_events where id='ee630000-0000-4000-8000-000000000201'and property_id is null and action='settings.organization_saved'and actor_id='ee630000-0000-4000-8000-000000000101'),'settings have actual actor and organization scope');
select pg_temp.throws($q$update public.organizations set name='Unrecorded override'where id='ee630000-0000-4000-8000-000000000001'$q$,'adopted organization name requires recorded decision');
select pg_temp.throws($q$select pg_temp.decide('ee630000-0000-4000-8000-000000000203',pg_temp.org_input()||'{"timezone":"Invalid/Zone"}')$q$,'invalid time zone cannot be saved');
select pg_temp.throws($q$select pg_temp.decide('ee630000-0000-4000-8000-000000000203',pg_temp.org_input()||'{"private":"injected"}')$q$,'unknown organization fields cannot be overwritten');
insert into st values('profileInput',pg_temp.personal_input());
select pg_temp.check_it(pg_temp.decide('ee630000-0000-4000-8000-000000000204',(select v from st where k='profileInput'),'ee630000-0000-4000-8000-000000000102')->>'state'='saved','viewer can save their own exact display name');
select pg_temp.check_it(public.team_member_view('ee630000-0000-4000-8000-000000000102')->>'name'='Reviewed display name','team directory sees recorded profile name');
update auth.users set last_sign_in_at=clock_timestamp(),raw_user_meta_data=raw_user_meta_data||'{"full_name":"Stale metadata name"}'where id='ee630000-0000-4000-8000-000000000102';
select pg_temp.check_it(public.team_member_view('ee630000-0000-4000-8000-000000000102')->>'name'='Reviewed display name','later auth updates cannot overwrite recorded profile name');
update auth.users set raw_user_meta_data=raw_user_meta_data||'{"full_name":"Updated untouched account"}'where id='ee630000-0000-4000-8000-000000000103';
select pg_temp.check_it(public.team_member_view('ee630000-0000-4000-8000-000000000103')->>'name'='Updated untouched account','untouched account metadata synchronization remains compatible');
select pg_temp.throws($q$update public.profiles set full_name='Raw overwrite'where id='ee630000-0000-4000-8000-000000000102'$q$,'adopted profile name requires recorded decision');
select pg_temp.check_it(pg_temp.decide('ee630000-0000-4000-8000-000000000204',(select v from st where k='profileInput'),'ee630000-0000-4000-8000-000000000102')->>'state'='replayed','profile response replays despite later auth activity');
select pg_temp.check_it(pg_temp.decide('ee630000-0000-4000-8000-000000000205',pg_temp.appearance_input(),'ee630000-0000-4000-8000-000000000102')->>'state'='saved','viewer can save appearance separately from organization control');
select pg_temp.check_it((select preferences->>'private'='PRIVATE-PREFERENCE-FIXTURE'and preferences->>'theme'='dark'and preferences->>'accent_color'='emerald'from public.profiles where id='ee630000-0000-4000-8000-000000000102'),'appearance saves exact supported values and preserves private unrelated preferences');
select pg_temp.throws($q$update public.profiles set preferences=preferences||'{"theme":"light"}'where id='ee630000-0000-4000-8000-000000000102'$q$,'adopted appearance bypass held');
select pg_temp.check_it(pg_temp.read_account('{"kind":"detail","section":"personal","decisionId":"ee630000-0000-4000-8000-000000000205"}')->>'state'='not_found','administrator cannot inspect another account personal history');
select pg_temp.check_it(pg_temp.read_account('{"kind":"history","section":"personal"}','ee630000-0000-4000-8000-000000000102')->>'total'='2','own complete personal history remains accessible');
select pg_temp.check_it(pg_temp.read_account('{"kind":"history","section":"organization"}','ee630000-0000-4000-8000-000000000102')->>'total'='1','members can inspect safe organization settings history');
select pg_temp.check_it(pg_temp.decide('ee630000-0000-4000-8000-000000000206','{"operation":"cancel_unused","section":"personal","inputHash":"cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc","reason":"Cancel unused profile request"}','ee630000-0000-4000-8000-000000000102')->>'kind'='cancelled','unused personal request cancellation recorded');
select pg_temp.check_it(pg_temp.decide('ee630000-0000-4000-8000-000000000206',pg_temp.personal_input(),'ee630000-0000-4000-8000-000000000102')->>'state'='decision_cancelled','late cancelled profile write is held');
select pg_temp.check_it(pg_temp.decide('ee630000-0000-4000-8000-000000000204','{"operation":"cancel_unused","section":"personal","inputHash":"cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc","reason":"Cancel unused profile request"}','ee630000-0000-4000-8000-000000000102')->>'kind'='profile_saved','cancelling a saved write recovers it without undo');
create function pg_temp.fail_action()returns trigger language plpgsql as $$begin if new.org_id='ee630000-0000-4000-8000-000000000001'then raise exception 'Fixture recording failure';end if;return new;end$$;
create trigger settings_fixture_recording before insert on public.shared_action_events for each row execute function pg_temp.fail_action();
select pg_temp.throws($q$select pg_temp.decide('ee630000-0000-4000-8000-000000000207',pg_temp.personal_input('ee630000-0000-4000-8000-000000000102','Should roll back'),'ee630000-0000-4000-8000-000000000102')$q$,'failed event rolls back profile update');
drop trigger settings_fixture_recording on public.shared_action_events;
select pg_temp.check_it(public.team_member_view('ee630000-0000-4000-8000-000000000102')->>'name'='Reviewed display name'and not exists(select 1 from public.account_settings_decisions where id='ee630000-0000-4000-8000-000000000207'),'recording failure leaves no partial profile or decision');
select pg_temp.throws($q$delete from public.account_settings_decisions where id='ee630000-0000-4000-8000-000000000201'$q$,'settings history remains immutable');
select pg_temp.check_it(not exists(select 1 from public.shared_action_events where org_id='ee630000-0000-4000-8000-000000000001'and(training_eligible or request::text like'%fixture.invalid%'or request::text like'%PRIVATE%'or after_state::text like'%display name%')),'shared settings actions exclude private values and training eligibility');
grant select,insert,update on assertion_count,st to service_role;
set local role service_role;
select pg_temp.check_it(pg_temp.read_account()->>'state'='ready','application role can read saved safe settings');
select pg_temp.check_it(pg_temp.decide('ee630000-0000-4000-8000-000000000208',pg_temp.org_input('Account settings SQL fixture'))->>'state'='saved','application role can save organization settings');
select pg_temp.check_it(pg_temp.decide('ee630000-0000-4000-8000-000000000209',pg_temp.personal_input('ee630000-0000-4000-8000-000000000102','Service recorded name'),'ee630000-0000-4000-8000-000000000102')->>'state'='saved','application role can save own profile');
reset role;
select pg_temp.check_it(not has_table_privilege('authenticated','public.account_settings_decisions','SELECT')and not has_function_privilege('authenticated','public.decide_account_settings(uuid,uuid,uuid,jsonb)','EXECUTE'),'private settings commands and history are service-only');
do $$declare n int;begin for n in 1001..2025 loop perform pg_temp.decide(('ee630000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,pg_temp.personal_input('ee630000-0000-4000-8000-000000000102','Paged account name '||n),'ee630000-0000-4000-8000-000000000102');end loop;end$$;
select pg_temp.check_it(pg_temp.read_account('{"kind":"history","section":"personal"}','ee630000-0000-4000-8000-000000000102')->>'total'='1029','complete personal history exceeds REST row limits');
insert into st values('fullHistory',pg_temp.read_account('{"kind":"history","section":"personal"}','ee630000-0000-4000-8000-000000000102'));
select pg_temp.check_it(jsonb_array_length(pg_temp.read_account(jsonb_build_object('kind','history','section','personal','offset',1020,'expectedHash',(select v->>'pageHash'from st where k='fullHistory')),'ee630000-0000-4000-8000-000000000102')->'items')=9,'final personal history page remains reachable');
select pg_temp.check_it(pg_temp.decide('ee630000-0000-4000-8000-000000003001',pg_temp.personal_input('ee630000-0000-4000-8000-000000000102','Changed while paging'),'ee630000-0000-4000-8000-000000000102')->>'state'='saved','another exact history decision can append');
select pg_temp.check_it(pg_temp.read_account(jsonb_build_object('kind','history','section','personal','offset',20,'expectedHash',(select v->>'pageHash'from st where k='fullHistory')),'ee630000-0000-4000-8000-000000000102')->>'state'='history_changed','history pagination detects a new native decision');
select pg_temp.check_it(public.decide_team_access('ee630000-0000-4000-8000-000000004001','ee630000-0000-4000-8000-000000000001','ee630000-0000-4000-8000-000000000101','{"operation":"create_invitation","email":"account-103@fixture.invalid","role":"viewer","expiresInDays":7,"confirmed":true,"reason":"Review supplied account invitation"}',repeat('7',64))->>'state'='saved','team invitation retains exact organization identity');
insert into st values('invitationReview',jsonb_build_object('operation','decline','invitationHash',public.team_join_context('ee630000-0000-4000-8000-000000000103',repeat('7',64))->>'invitationHash','confirmed',true,'reason','Review exact invited organization'));
select pg_temp.check_it(pg_temp.decide('ee630000-0000-4000-8000-000000004002',pg_temp.org_input('Corrected organization identity'))->>'state'='saved','recorded name change updates reviewed organization identity');
select pg_temp.check_it(public.decide_team_join('ee630000-0000-4000-8000-000000004003','ee630000-0000-4000-8000-000000000103',repeat('7',64),(select v from st where k='invitationReview'))->>'state'='invitation_changed','old invitation review is held after organization identity changes');
select n as passed_assertions from assertion_count;
ROLLBACK;
